// VJUGA rev B Video card full-package structural LVS netlist (R5.V1).
// Independently states every populated digital package U1..U22 and includes power.
// Behaviour belongs in revb_video_card_ttl.v and the GAL sources; this file is only
// the second connectivity representation used by sync/lvs.py.
`default_nettype none

module osc_25m175_lvs(inout wire OE,GND,CLKOUT,VCC); endmodule
module ttl393_lvs(inout wire CLK1,CLR1,Q1A,Q1B,Q1C,Q1D,GND,Q2D,Q2C,Q2B,Q2A,CLR2,CLK2,VCC); endmodule
module gal_hdec_lvs(inout wire DOTCLK,HC0,HC1,HC2,HC3,HC4,HC5,HC6,HC7,HC8,HC9,GND,RESET_N,H_END,HSYNC_N,H_ACTIVE,BYTE_TICK,FI_LOAD_N,SR_LOAD_N,SR_INH,FETCH,RB_STROBE,VID_HDEC_O23_NC,VCC5); endmodule
module gal_vdec_lvs(inout wire RB_STROBE,VC0,VC1,VC2,VC3,VC4,VC5,VC6,VC7,VC8,VC9,GND,RESET_N,V_END,VSYNC_N,FRAME_DIV2_NC,FRAME_DIV1_NC,FRAME_DIV0_NC,FRAME_TOP_N,FRAME_TICK,RB_CLK,V_ACTIVE,VID_VDEC_O23_NC,VCC5); endmodule
module gal_ctrl_lvs(inout wire FETCH,A11,A12,A13,A14,A15,MREQ_N,RD_N,WR_N,MODE0,MODE1,GND,RESET_N,WAIT_N,MUX_SEL,D245_DIR,D245_OE,FB_CE_N,FB_WE_N,FB_OE_N,VID_CTRL_O21_NC,VID_CTRL_O22_NC,VID_CTRL_CPUACC_NC,VCC5); endmodule
