    gal_vdec_lvs U_VDEC(.RB_STROBE(RB_STROBE),.VC0(VC0),.VC1(VC1),.VC2(VC2),.VC3(VC3),.VC4(VC4),.VC5(VC5),.VC6(VC6),.VC7(VC7),.VC8(VC8),.VC9(VC9),.GND(GND),.RESET_N(RESET_N),.V_END(V_END),.VSYNC_N(VSYNC_N),.FRAME_DIV2_NC(FRAME_DIV2_NC),.FRAME_DIV1_NC(FRAME_DIV1_NC),.FRAME_DIV0_NC(FRAME_DIV0_NC),.FRAME_TOP_N(FRAME_TOP_N),.FRAME_TICK(FRAME_TICK),.RB_CLK(RB_CLK),.V_ACTIVE(V_ACTIVE),.VID_VDEC_O23_NC(VID_VDEC_O23_NC),.VCC5(VCC5));
